class Clipboard{static async CanRead(){const t=await navigator.permissions.query({name:"clipboard-read"});return"granted"===t.state||"prompt"===t.state}static async CanWrite(){try{const t=await navigator.permissions.query({name:"clipboard-write"});return"granted"===t.state||"prompt"===t.state}catch{return!!navigator.clipboard}}static ReadText=()=>navigator.clipboard.readText();static WriteText=t=>navigator.clipboard.writeText(t);static async ReadImage(){const t=await navigator.clipboard.read();for(const e of t)for(const t of["image/png","image/jpeg","image/gif","image/webp"])if(e.types.includes(t))return await e.getType(t);return null}static WriteImage=async t=>{const e=new ClipboardItem({[t.type]:t});return navigator.clipboard.write([e])};static WriteMultiple=async(t,e)=>{const a=new Blob([t],{type:"text/plain"}),i=new ClipboardItem({"text/plain":a,[e.type]:e});return navigator.clipboard.write([i])}}window.GizmoWebJSInterop=class GizmoWebJSInterop{static Clipboard=Clipboard};
